contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an amount to deposit from this test contract into c (so address(c).balance > 0),
    // then attempt migrateTo by specifying who calls it: either this contract should act as creator
    // or not. Because the checker deploys a fresh c and passes it to this test's constructor, the
    // deployer of c is the test harness, not this contract; however the only externally visible
    // way to trigger migrateTo is via calling c.migrateTo. Here we assert that when migrateTo
    // succeeds (i.e., called by the creator), address(c).balance becomes zero; and when it is
    // called by a non-creator it must revert and leave address(c).balance unchanged. We also
    // assert that a non-creator's per-address recorded balance (queried via the public getter)
    // is not decreased by migrateTo: migrateTo only moves the contract's global balance.

    function run(uint256 depositAmount, address to) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // ensure the test contract has enough Ether to deposit
        require(address(this).balance >= depositAmount);

        // record c's global balance before any action
        uint256 c_before = address(c).balance;

        // record this contract's recorded balance in c (via the public balances getter)
        // Note: balances is defined in C as mapping(address=>uint256) balances; it is not public in
        // the provided contract, so we cannot call c.balances(...). Instead we observe that C has
        // no public getter for per-address balances. To adhere to the constraints, we must only
        // observe address(c).balance and effects of migrateTo. Therefore we adjust the rule to
        // assert only on global balance and revert behavior.

        // deposit into c to ensure there is some Ether to migrate; deposit may revert if C.deposit
        // assert inside deposit fails due to overflow — in that case the test will revert and is
        // not required to reach the final assert. To avoid hitting the assert inside C.deposit, we
        // constrain depositAmount to be small enough: require depositAmount > 0.
        require(depositAmount > 0);

        // perform deposit from this contract into c
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // record c balance after deposit
        uint256 c_after_deposit = address(c).balance;

        // Try calling migrateTo as this contract (which is NOT the creator of C since creator is
        // the account that deployed C — the test harness). Capture whether it reverts.
        bool migrateReverted;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            migrateReverted = true;
        } else {
            migrateReverted = false;
        }

        uint256 c_final = address(c).balance;

        // General rule:
        // - If migrateTo did NOT revert, then it must have moved the entire contract balance out,
        //   so address(c).balance == 0.
        // - If migrateTo DID revert (caller was not creator), c's balance must be unchanged from
        //   just after deposit (i.e., migrate attempted no global transfer).
        assert((!migrateReverted && c_final == 0) || (migrateReverted && c_final == c_after_deposit));
    }

    receive() external payable { }
}

